import json

from pydantic import BaseModel, ValidationError

from client_llm import cfg, client
from recettes.recherche import RECETTES, par_ingredient, trouver   # chapitres 2/4

# ---- les vraies fonctions (compactes : on renvoie le minimum utile) ----

def chercher_recettes(ingredient: str) -> dict:
    noms = par_ingredient(RECETTES, ingredient.lower().strip())
    return {"recettes": [{"nom": n,
                          "temps_min": trouver(RECETTES, n)["temps_min"]}
                         for n in noms]}

def detail_recette(nom: str) -> dict:
    r = trouver(RECETTES, nom.lower().strip())
    if r is None:
        return {"erreur": f"recette inconnue : {nom}. "
                          f"Recettes disponibles : {[x['nom'] for x in RECETTES]}"}
    return {"nom": r["nom"], "temps_min": r["temps_min"],
            "ingredients": r["ingredients"]}

# ---- validation des arguments : le modèle PROPOSE, ce code DISPOSE ----

class ArgsChercher(BaseModel):
    ingredient: str

class ArgsDetail(BaseModel):
    nom: str

REGISTRE = {
    "chercher_recettes": (ArgsChercher, chercher_recettes),
    "detail_recette": (ArgsDetail, detail_recette),
}

def executer(nom_outil: str, args_bruts: str) -> dict:
    if nom_outil not in REGISTRE:
        return {"erreur": f"outil inconnu : {nom_outil}"}
    modele, fonction = REGISTRE[nom_outil]
    try:
        args = modele(**json.loads(args_bruts))
    except (json.JSONDecodeError, ValidationError) as exc:
        return {"erreur": f"arguments invalides : {exc}"}
    return fonction(**args.model_dump())

TOOLS = [
    {"type": "function", "function": {
        "name": "chercher_recettes",
        "description": "Cherche les recettes contenant un ingrédient. À utiliser "
                       "dès que l'utilisateur mentionne un ingrédient disponible.",
        "parameters": {"type": "object",
                       "properties": {"ingredient": {"type": "string",
                                      "description": "un seul ingrédient, ex. 'oeufs'"}},
                       "required": ["ingredient"]}}},
    {"type": "function", "function": {
        "name": "detail_recette",
        "description": "Donne ingrédients et temps d'une recette EXACTE (nom "
                       "obtenu via chercher_recettes).",
        "parameters": {"type": "object",
                       "properties": {"nom": {"type": "string"}},
                       "required": ["nom"]}}},
]

SYSTEM = ("Assistant culinaire de l'app. Utilise les outils pour répondre "
          "factuellement depuis la base de recettes ; n'invente jamais une recette. "
          "Réponses courtes, en français.")


def dialoguer(question: str, max_tours: int = 6) -> str:
    messages = [{"role": "system", "content": SYSTEM},
                {"role": "user", "content": question}]
    for tour in range(max_tours):
        r = client.chat.completions.create(model=cfg.deployment,
                                           messages=messages, tools=TOOLS,
                                           temperature=0.2)
        msg = r.choices[0].message
        if not msg.tool_calls:
            return msg.content
        messages.append(msg)
        for call in msg.tool_calls:
            print(f"→ {call.function.name}({call.function.arguments})")
            resultat = executer(call.function.name, call.function.arguments)
            print(f"← {json.dumps(resultat, ensure_ascii=False)[:120]}")
            messages.append({"role": "tool", "tool_call_id": call.id,
                             "content": json.dumps(resultat, ensure_ascii=False)})
    return "Je n'ai pas réussi à conclure (limite de tours atteinte)."


print(dialoguer("Trouve une recette avec des oeufs et détaille la plus rapide"))
```

Trace du scénario chaîné (4c) :

```
→ chercher_recettes({"ingredient": "oeufs"})
← {"recettes": [{"nom": "carbonara", "temps_min": 25}, {"nom": "omelette", "temps_min": 10}]}
→ detail_recette({"nom": "omelette"})
← {"nom": "omelette", "temps_min": 10, "ingredients": ["oeufs", "beurre"]}
« La plus rapide est l'omelette (10 min) : oeufs et beurre. »
```

Les points structurants :

- **Le chaînage a émergé tout seul** : personne n'a codé « d'abord chercher, ensuite détailler » — le modèle a décidé de la séquence à partir des descriptions d'outils. C'est le germe de l'agent du chapitre 18.
- **L'erreur est une donnée** : `detail_recette("tiramisu")` renvoie `{"erreur": ..., disponibles: [...]}` — l'assistant lit ce résultat et répond « je n'ai pas cette recette, mais je peux te proposer... ». Un raise aurait cassé la boucle ; une erreur STRUCTURÉE la nourrit.
- La validation Pydantic par outil est le poste-frontière : quoi que génère le modèle (JSON cassé, champ en trop, injection dans le texte utilisateur), seules des valeurs conformes atteignent tes fonctions.
